#include <iostream>
#include <vector>
#include <string>

class Student {
private:
    std::string name;
    int id;
    std::vector<int> grades;

public:
    Student(std::string n, int i) : name(n), id(i) {}

    void addGrade(int grade) {
        grades.push_back(grade)
    }

    double getAverage() {
        if (grades.empty()) return 0.0;
        int sum = 0;
        for (int i = 0; i < grades.size(); i++) {
            sum += grades[i];
        }
        return (double)sum / grades.size();
    }

    void printInfo() {
        std::cout << "Student: " << name << " (ID: " << id << ")\n";
        std::cout << "Average: " << getAverage() << "\n";
    }
};

int main() {
    Student s1("Alice", 101);
    s1.addGrade(90);
    s1.addGrade(85);
    s1.addGrade(95);

    s1.printInfo();

    return 0;
}
